async function departmentData(label,path,fallback){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);
  try{const response=await fetch(`${apiBase}/${path}`,{cache:'no-store',credentials:'same-origin',signal:controller.signal});if(response.status===401){const error=new Error('Your staff session expired. Sign in again.');error.sessionExpired=true;throw error;}let data;try{data=await response.json();}catch{throw new Error(`${label} returned an unreadable response (HTTP ${response.status}).`);}if(!response.ok)throw new Error(`${label} could not load (HTTP ${response.status}). ${data.error||'Try again.'}`);return {data};}
  catch(error){if(error.sessionExpired)throw error;const message=error.name==='AbortError'?`${label} took too long to respond. Try again.`:error.message||`${label} could not load.`;if(fallback!==undefined)return {data:fallback,error:message};throw new Error(message);}
  finally{clearTimeout(timer);}
}
