// v44 duplicate policy: exact name, registration/index number and score matches are
// informational and counted once. Conflicts expose correction and audited removal tools.
function duplicateReconciliationPanel(record){
  const groups=Array.isArray(record?.duplicateReconciliation)?record.duplicateReconciliation:[];
  if(!groups.length)return '';
  const authorised=can('project-work','administrator');
  const fullSheet=o=>{const rows=Array.isArray(o.scoreRows)?o.scoreRows:[];return `<details class="duplicate-sheet-details"><summary>View extracted score sheet (${rows.length} score row${rows.length===1?'':'s'})</summary><div class="table-scroll"><table class="score-review-table"><thead><tr><th>S/N</th><th>NAME</th><th>REGISTRATION / INDEX NO.</th><th>GROUP NO.</th><th>TOTAL SCORE</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${r.sourceIndex===o.sourceIndex?'duplicate-focus-row':''} ${r.included===false?'score-row-excluded':''}"><td>${esc(r.originalSn||i+1)}</td><td>${esc(r.name)}</td><td>${esc(r.registrationNo)}</td><td>${esc(r.groupNo)}</td><td>${esc(r.totalScore)}</td></tr>`).join('')}</tbody></table></div></details>`};
  const conflicts=groups.filter(g=>g.classification!=='exact').length;
  return `<section class="duplicate-reconciliation"><div class="score-review-head"><div><h3>Duplicate Registration / Index Review</h3><p>Exact matches in student name, registration/index number and score are accepted and counted once in approved reports. If any value differs, correct the index number or remove the affected row from approved records. The original workbook is preserved.</p></div><strong>${groups.length} detected</strong></div>${groups.map(g=>{const exact=g.classification==='exact';return `<div class="duplicate-group ${exact?'duplicate-exact':'duplicate-conflict'}"><div class="duplicate-group-heading"><h4>${esc(g.registrationNo)}</h4><span class="duplicate-policy-badge ${exact?'exact':'conflict'}">${esc(g.classificationLabel||'Conflicting duplicate')}</span></div>${exact?'<p class="duplicate-policy-note">No action is required. This student will appear once in consolidated and master score reports.</p>':'<p class="duplicate-policy-note">Values differ. Correct the affected registration/index number or select a row for removal.</p>'}<div class="table-scroll"><table><thead><tr><th>Score Sheet</th><th>Supervisor / Examiner</th><th>Student</th><th>Registration / Index No.</th><th>Group</th><th>Score</th><th>Source</th><th>Admin action</th></tr></thead><tbody>${g.occurrences.map(o=>{const editable=authorised&&!exact&&o.included!==false;return `<tr class="${o.included===false?'score-row-excluded':''}"><td><strong>${esc(o.reference)}</strong><br><small>${esc(o.status)}</small></td><td>${esc(o.supervisorName)}<br><small>${esc(o.supervisorEmail)}</small></td><td>${esc(o.studentName)}</td><td><input class="duplicate-reg-input" data-submission-id="${esc(o.submissionId)}" data-source-index="${Number(o.sourceIndex)}" value="${esc(o.registrationNo)}" ${editable?'':'disabled'}></td><td>${esc(o.groupNo)}</td><td>${esc(o.totalScore)}</td><td><a class="btn small" href="${apiBase}/submissions/${encodeURIComponent(o.submissionId)}/files/scoresFile">Open Original</a></td><td>${o.included===false?'<strong>Removed from approved records</strong>':editable?`<label class="duplicate-remove-label"><input class="duplicate-remove-check" type="checkbox" data-submission-id="${esc(o.submissionId)}" data-source-index="${Number(o.sourceIndex)}"> Remove this row</label><button class="btn small danger duplicate-delete-submission" type="button" onclick="deleteOneSubmission('${esc(o.submissionId)}','score-sheet submission')">Delete whole submission</button>`:'No action needed'}</td></tr><tr class="duplicate-sheet-preview-row"><td colspan="8">${fullSheet(o)}</td></tr>`}).join('')}</tbody></table></div></div>`}).join('')}${authorised&&conflicts?`<div class="dialog-actions"><button class="btn approve" type="button" onclick="reconcileDuplicateScores('${esc(record.id)}')">Apply Corrections / Removals &amp; Re-approve</button></div>`:''}</section>`;
}

function fieldDuplicateReconciliationPanel(record){
  const groups=Array.isArray(record?.duplicateReconciliation)?record.duplicateReconciliation:[];
  if(!groups.length)return '';
  const authorised=can('field-experience','administrator');
  const scoreText=row=>(row.scoreHeaders||[]).map((header,index)=>`${header}: ${row.scoreValues?.[index]??''}`).join(' · ');
  const fullSheet=o=>{const rows=Array.isArray(o.scoreRows)?o.scoreRows:[];return `<details class="duplicate-sheet-details"><summary>View extracted score sheet (${rows.length} score row${rows.length===1?'':'s'})</summary><div class="table-scroll"><table class="score-review-table"><thead><tr><th>S/N</th><th>REGISTRATION</th><th>NAME OF STUDENT</th><th>SCORE(S)</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${r.sourceIndex===o.sourceIndex?'duplicate-focus-row':''} ${r.included===false?'score-row-excluded':''}"><td>${esc(r.originalSn||i+1)}</td><td>${esc(r.registrationNo)}</td><td>${esc(r.name)}</td><td>${esc(scoreText(r))}</td></tr>`).join('')}</tbody></table></div></details>`};
  const conflicts=groups.filter(g=>g.classification!=='exact').length;
  return `<section class="duplicate-reconciliation"><div class="score-review-head"><div><h3>Duplicate Registration Review</h3><p>Exact matches in student name, registration number and all score fields are accepted and counted once in approved reports. Conflicting entries can be corrected or removed from approved records without changing the uploaded workbook.</p></div><strong>${groups.length} detected</strong></div>${groups.map(g=>{const exact=g.classification==='exact';return `<div class="duplicate-group ${exact?'duplicate-exact':'duplicate-conflict'}"><div class="duplicate-group-heading"><h4>${esc(g.registrationNo)}</h4><span class="duplicate-policy-badge ${exact?'exact':'conflict'}">${esc(g.classificationLabel||'Conflicting duplicate')}</span></div>${exact?'<p class="duplicate-policy-note">No action is required. This student will appear once in the relevant approved score report.</p>':'<p class="duplicate-policy-note">Values differ. Correct the affected registration number or select a row for removal.</p>'}<div class="table-scroll"><table><thead><tr><th>Score Sheet</th><th>Supervisor / Examiner</th><th>Student</th><th>Registration</th><th>Score(s)</th><th>Source</th><th>Admin action</th></tr></thead><tbody>${g.occurrences.map(o=>{const editable=authorised&&!exact&&o.included!==false;return `<tr class="${o.included===false?'score-row-excluded':''}"><td><strong>${esc(o.reference)}</strong><br><small>${esc(o.assessmentLabel||o.status)}</small></td><td>${esc(o.supervisorName)}<br><small>${esc(o.supervisorEmail)}</small></td><td>${esc(o.studentName)}</td><td><input class="duplicate-reg-input" data-submission-id="${esc(o.submissionId)}" data-source-index="${Number(o.sourceIndex)}" value="${esc(o.registrationNo)}" ${editable?'':'disabled'}></td><td>${esc(scoreText(o))}</td><td><a class="btn small" href="${apiBase}/submissions/${encodeURIComponent(o.submissionId)}/files/scoresFile">Open Original</a></td><td>${o.included===false?'<strong>Removed from approved records</strong>':editable?`<label class="duplicate-remove-label"><input class="duplicate-remove-check" type="checkbox" data-submission-id="${esc(o.submissionId)}" data-source-index="${Number(o.sourceIndex)}"> Remove this row</label><button class="btn small danger duplicate-delete-submission" type="button" onclick="deleteOneSubmission('${esc(o.submissionId)}','score-sheet submission')">Delete whole submission</button>`:'No action needed'}</td></tr><tr class="duplicate-sheet-preview-row"><td colspan="7">${fullSheet(o)}</td></tr>`}).join('')}</tbody></table></div></div>`}).join('')}${authorised&&conflicts?`<div class="dialog-actions"><button class="btn approve" type="button" onclick="reconcileDuplicateScores('${esc(record.id)}','field-experience')">Apply Corrections / Removals &amp; Re-approve</button></div>`:''}</section>`;
}

window.reconcileDuplicateScores=async(currentId,section='project-work')=>{
  const checked=[...document.querySelectorAll('#detailDialog .duplicate-remove-check:checked')];
  const removedRows=checked.map(input=>({submissionId:input.dataset.submissionId,sourceIndex:Number(input.dataset.sourceIndex)}));
  const removedKeys=new Set(removedRows.map(item=>`${item.submissionId}:${item.sourceIndex}`));
  const inputs=[...document.querySelectorAll('#detailDialog .duplicate-reg-input:not(:disabled)')];
  const edits=inputs.filter(input=>!removedKeys.has(`${input.dataset.submissionId}:${Number(input.dataset.sourceIndex)}`)).map(input=>({submissionId:input.dataset.submissionId,sourceIndex:Number(input.dataset.sourceIndex),registrationNo:input.value.trim()}));
  if(edits.some(item=>!item.registrationNo))return alert('Registration/index number cannot be blank.');
  if(!edits.length&&!removedRows.length)return alert('Choose a correction or select a conflicting row to remove.');
  let removalReason='';
  if(removedRows.length){const reasons=await chooseApprovalReasons({title:'Reasons for removing selected duplicate rows',options:approvalReasonOptions.duplicateRemoval,defaults:['wrong-entry']});if(!reasons)return;removalReason=reasons.text;}
  const affectedSubmissionIds=[...new Set([...edits,...removedRows].map(item=>item.submissionId))];
  const actionText=[edits.length?`${edits.length} correction(s)`:null,removedRows.length?`${removedRows.length} row removal(s)`:null].filter(Boolean).join(' and ');
  if(!confirm(`Apply ${actionText} and re-approve ${affectedSubmissionIds.length} participating score sheet${affectedSubmissionIds.length===1?'':'s'}?`))return;
  const endpoint=section==='field-experience'?'field-experience':'project-work';
  const response=await fetch(`${apiBase}/${endpoint}/${encodeURIComponent(currentId)}/reconcile-duplicates`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({edits,removedRows,removalReason,affectedSubmissionIds})});
  const data=await response.json().catch(()=>({}));
  if(!response.ok)return alert(data.error||'Could not reconcile duplicate score sheets.');
  if(dialog.open)dialog.close();await load();
  alert(`${data.reapprovedSubmissions||affectedSubmissionIds.length} score sheet(s) re-approved. ${data.correctedRows||0} row(s) corrected and ${data.removedRows||0} row(s) removed from approved records.`);
};
